func serverComparisonSources(t *testing.T) []serverComparisonSource {
	t.Helper()
	if len(serverComparisonInventory) != 86 || len(serverComparisonAdmission) != 86 {
		t.Fatal("incomplete86-source wire inventory")
	}
	seen := map[uint32]bool{}
	for i, s := range serverComparisonInventory {
		if seen[s.oid] {
			t.Fatal("duplicate wire source", s.oid)
		}
		seen[s.oid] = true
		row, err := hex.DecodeString(serverComparisonAdmission[i])
		if err != nil || len(row) != 86 {
			t.Fatalf("source%s admission row incomplete: %v", s.name, err)
		}
		for _, mask := range row {
			if mask&128 != 0 {
				t.Fatal("invalid admission mask", s.name)
			}
		}
	}
	return serverComparisonInventory
}
func (s serverComparisonSource) formats() []int {
	var out []int
	if s.textInput {
		out = append(out, 0)
	}
	if s.binaryInput {
		out = append(out, 1)
	}
	return out
}
func (s serverComparisonSource) input(t *testing.T, format int) []byte {
	t.Helper()
	if format == 0 {
		return []byte(s.text)
	}
	raw, err := hex.DecodeString(s.wire)
	if err != nil {
		t.Fatal(err)
	}
	if raw == nil {
		return []byte{}
	}
	return raw
}
func (s serverComparisonSource) label() string {
	return strconv.FormatUint(uint64(s.oid), 10) + "_" + s.name
}
